#include <bits/stdc++.h>
using namespace std;

const int N = 5e5 + 10;
int n, m;
int a[N];
int last[N];
vector<int> g[N];
long long sz[N];
long long ans[N];

void dfs(int u) {
    sz[u] = 1;
    for (int v : g[u]) {
        dfs(v);
        sz[u] += sz[v];
    }
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        last[a[i]] = i;
    }
    int root = n + 1;
    for (int s = 1; s <= n; s++) {
        int fa = last[a[s]] + 1;   // 同点数最后一次出现的下一张
        g[fa].push_back(s);
    }
    dfs(root);
    for (int i = 1; i <= n; i++) {
        ans[a[i]] += sz[i];        // 有多少局的路径经过位置 i
    }
    for (int i = 1; i <= m; i++) cout << ans[i] << " ";
    return 0;
}
